package com.mybank.pbac.controller; import com.mybank.pbac.model.*; import com.mybank.pbac.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/obligations") class ObligationController {private final ObligationRepository r;ObligationController(ObligationRepository r){this.r=r;}@GetMapping List<Obligation> all(){return r.findAll();}@PostMapping Obligation add(@RequestBody Obligation x){x.setId(null);return r.save(x);}@PutMapping("/{id}") Obligation edit(@PathVariable Long id,@RequestBody Obligation x){x.setId(id);return r.save(x);}@DeleteMapping("/{id}") void del(@PathVariable Long id){r.deleteById(id);}}
@RestController @RequestMapping("/api/attributes") class AttributeController {private final AttributeDefinitionRepository r;AttributeController(AttributeDefinitionRepository r){this.r=r;}@GetMapping List<AttributeDefinition> all(){return r.findAll();}@PostMapping AttributeDefinition add(@RequestBody AttributeDefinition x){x.setId(null);return r.save(x);}@PutMapping("/{id}") AttributeDefinition edit(@PathVariable Long id,@RequestBody AttributeDefinition x){x.setId(id);return r.save(x);}@DeleteMapping("/{id}") void del(@PathVariable Long id){r.deleteById(id);}}
@RestController @RequestMapping("/api/audit") class AuditController {private final AuditEventRepository r;AuditController(AuditEventRepository r){this.r=r;}@GetMapping List<AuditEvent> all(){return r.findAll();}}
